export const KNOWLEDGE_SOURCE_TYPES = Object.freeze(['news','macro-release','investor-letter','investor-disclosure','research','other']);
export const KNOWLEDGE_CHOICES = Object.freeze({level:['macro','micro','mixed','uncertain'],horizon:['short_term','long_term','mixed','uncertain'],sentiment:['positive','negative','neutral','mixed','uncertain'],novelty:['new_fact','corroboration','known','uncertain'],scopeKind:['global','asset_class','instrument','economy','sector','mixed','uncertain']});
export const disabledExternalKnowledge = () => ({enabled:false,mode:'pinned',documentPins:[],sourceTypes:[],authorIds:[],levels:[],horizons:[],maxAgeHours:720,maxItems:8,approval:'APPROVED_ONLY'});
export function validExternalKnowledgePolicy(p){
  const keys=['enabled','mode','documentPins','sourceTypes','authorIds','levels','horizons','maxAgeHours','maxItems','approval'],ids=v=>Array.isArray(v)&&v.length<=100&&new Set(v).size===v.length&&v.every(x=>typeof x==='string'&&/^[a-zA-Z0-9][a-zA-Z0-9_.:@/-]{0,199}$/.test(x)),choices=(v,allowed)=>ids(v)&&v.every(x=>allowed.includes(x));
  return !!p&&typeof p==='object'&&!Array.isArray(p)&&Object.keys(p).length===keys.length&&keys.every(k=>Object.hasOwn(p,k))&&typeof p.enabled==='boolean'&&['pinned','subscribed'].includes(p.mode)&&p.approval==='APPROVED_ONLY'&&Number.isInteger(p.maxAgeHours)&&p.maxAgeHours>=1&&p.maxAgeHours<=87600&&Number.isInteger(p.maxItems)&&p.maxItems>=1&&p.maxItems<=12&&choices(p.sourceTypes,KNOWLEDGE_SOURCE_TYPES)&&ids(p.authorIds)&&choices(p.levels,KNOWLEDGE_CHOICES.level)&&choices(p.horizons,KNOWLEDGE_CHOICES.horizon)&&Array.isArray(p.documentPins)&&p.documentPins.length<=100&&new Set(p.documentPins.map(x=>x?.id)).size===p.documentPins.length&&p.documentPins.every(x=>x&&Object.keys(x).length===3&&ids([x.id])&&Number.isSafeInteger(x.version)&&x.version>0&&/^[a-f0-9]{64}$/.test(x.contentHash))&&(!p.enabled||(p.mode==='pinned'?p.documentPins.length>0:p.sourceTypes.length>0));
}
